import { useEffect, useState } from 'react';
import { api } from '../../api/api';
import PageHeader from '../../components/PageHeader';
import Loader from '../../components/Loader';

export default function AdminProfile() {
  const [profile, setProfile] = useState(null);
  useEffect(() => { api('/admin/me').then(setProfile); }, []);
  if (!profile) return <Loader />;

  const rows = [
    ['Name', profile.name],
    ['Title', profile.title],
    ['Email', profile.email],
    ['Phone', profile.phone],
    ['Office', profile.office],
    ['Date Appointed', profile.joined]
  ];

  return (
    <div>
      <PageHeader title="My Profile" subtitle="Administrator account details" />
      <div className="card profile-card">
        <div className="profile-card__head">
          <div className="avatar avatar--lg">{profile.name.charAt(0)}</div>
          <div><h3>{profile.name}</h3><p>{profile.title}</p></div>
        </div>
        <table className="table table--striped">
          <tbody>
            {rows.map(([k, v]) => <tr key={k}><td className="table__label">{k}</td><td>{v}</td></tr>)}
          </tbody>
        </table>
      </div>
    </div>
  );
}
